import numpy as np, loads as L
NX,NY=40,30
XS=np.arange(0,241,6.0); YS=np.arange(0,181,6.0)
def void_mask():
    m=np.zeros((NX,NY),bool)
    for nm,(x0,x1,y0,y1) in L.OPENINGS.items():
        for i in range(NX):
            for j in range(NY):
                cx0,cx1,cy0,cy1=XS[i],XS[i+1],YS[j],YS[j+1]
                if cx1>x0+1e-9 and cx0<x1-1e-9 and cy1>y0+1e-9 and cy0<y1-1e-9:
                    m[i,j]=True
    return m
VOID=void_mask()

def surcharge_map(scn, closed=False, superpose=False):
    strips=L.all_strips(L.GROUPS[scn])
    S=np.zeros((NX,NY))
    if not superpose:
        for d in strips:
            for i in range(NX):
                for j in range(NY):
                    v=L.cell_max_strip(d,XS[i],XS[i+1],YS[j],YS[j+1],closed)
                    if v>S[i,j]: S[i,j]=v
        return S
    # superpose within a wind direction (sampling-based max of sum within cell)
    dirs=sorted(set(d['wind'] for d in strips))
    for wd in dirs:
        ds=[d for d in strips if d['wind']==wd]
        for i in range(NX):
            for j in range(NY):
                # sample points across cell (fine) incl edges if closed
                n=13
                if closed:
                    xs=np.linspace(XS[i],XS[i+1],n); ys=np.linspace(YS[j],YS[j+1],n)
                else:
                    e=1e-6
                    xs=np.linspace(XS[i]+e,XS[i+1]-e,n); ys=np.linspace(YS[j]+e,YS[j+1]-e,n)
                best=0.0
                fns=[]
                for d in ds:
                    if L.cell_max_strip(d,XS[i],XS[i+1],YS[j],YS[j+1],closed)>0:
                        fns.append(L.strip_value_fn(d))
                if not fns: continue
                if len(fns)==1:
                    # exact
                    v=max(L.cell_max_strip(d,XS[i],XS[i+1],YS[j],YS[j+1],closed) for d in ds)
                    best=v
                else:
                    for x in xs:
                        for y in ys:
                            s=0.0
                            for fn,box in fns:
                                if box[0]-1e-9<=x<=box[1]+1e-9 and box[2]-1e-9<=y<=box[3]+1e-9:
                                    s+=fn(x,y)
                            best=max(best,s)
                    # ensure not below single max
                    best=max(best,max(L.cell_max_strip(d,XS[i],XS[i+1],YS[j],YS[j+1],closed) for d in ds))
                S[i,j]=max(S[i,j],best)
    return S

def uplift_map():
    a=L.A_ZONE
    U=np.zeros((NX,NY))
    for i in range(NX):
        for j in range(NY):
            cx0,cx1,cy0,cy1=XS[i],XS[i+1],YS[j],YS[j+1]
            # distance ranges to nearest edges
            dx_min=min(cx0, 240-cx1) if True else 0
            # min distance from any point in cell to x-edges
            dxm=min(cx0,240-cx1); dym=min(cy0,180-cy1)
            # zone 3 corner squares: point within a of two edges
            in3=False
            for (ex,ey) in [(0,0),(240,0),(0,180),(240,180)]:
                # corner square [ex-a or ex, ...]
                sx0,sx1=(0,a) if ex==0 else (240-a,240)
                sy0,sy1=(0,a) if ey==0 else (180-a,180)
                if cx1>sx0 and cx0<sx1 and cy1>sy0 and cy0<sy1: in3=True
            dmin=min(dxm,dym)
            if in3: U[i,j]=101.2
            elif dmin<a: U[i,j]=74.2
            elif dmin<2*a: U[i,j]=47.3
            else: U[i,j]=32.3
    return U
