import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spl
import loads as L
XN=np.arange(0,241,6.0); YN=np.arange(0,181,30.0)
NXn,NYn=len(XN),len(YN)   # 41 x 7
def nid(i,j): return j*NXn+i
NN=NXn*NYn; NDOF=2*NN
EA_J=87580.0; EA_G=221850.0; EA_E=74240.0
FRAMES={ # name: (dir, wall coordinate, bay from, bay to, k)
 'BF-X1':('X',0.0,30.0,60.0,55.0),'BF-X2':('X',0.0,180.0,210.0,55.0),
 'BF-X3':('X',180.0,60.0,90.0,18.0),'BF-X4':('X',180.0,150.0,180.0,18.0),
 'BF-Y1':('Y',0.0,30.0,60.0,22.0),'BF-Y2':('Y',0.0,120.0,150.0,22.0),
 'BF-Y3':('Y',240.0,60.0,90.0,68.0),'BF-Y4':('Y',240.0,90.0,120.0,68.0)}

def build_bars():
    bars=[]  # (n1,n2,dir,EA,L_in, tag)
    for i in range(NXn):
        ea=EA_J+(EA_E if i in (0,NXn-1) else 0.0)
        for j in range(NYn-1):
            bars.append((nid(i,j),nid(i,j+1),'y',ea,30*12.0,('J',i,j)))
    for j in range(NYn):
        ea=EA_G+(EA_E if j in (0,NYn-1) else 0.0)
        for i in range(NXn-1):
            bars.append((nid(i,j),nid(i+1,j),'x',ea,6*12.0,('G',i,j)))
    return bars
BARS=build_bars()

def frame_springs():
    sp_=[]
    for nm,(d,wall,b0,b1,k) in FRAMES.items():
        for c in (b0,b1):
            if d=='X':
                i=int(round(c/6)); j=int(round(wall/30)); dof=2*nid(i,j)
            else:
                i=int(round(wall/6)); j=int(round(c/30)); dof=2*nid(i,j)+1
            sp_.append((nm,dof,k/2.0))
    return sp_
SPRINGS=frame_springs()

def assemble(Gpanel, kreg=1e-3):
    """Gpanel: array (40,6) effective G' kip/in per panel (0 = no panel)"""
    rows=[];cols=[];vals=[]
    def add(dofs,k):
        for a in range(len(dofs)):
            for b in range(len(dofs)):
                rows.append(dofs[a]);cols.append(dofs[b]);vals.append(k[a,b])
    for (n1,n2,d,ea,Lb,tag) in BARS:
        k=ea/Lb
        off=0 if d=='x' else 1
        dofs=[2*n1+off,2*n2+off]
        add(dofs,k*np.array([[1,-1],[-1,1.0]]))
    a=72.0;b=360.0
    for i in range(40):
        for j in range(6):
            G=Gpanel[i,j]
            if G<=0: continue
            n1,n2,n3,n4=nid(i,j),nid(i+1,j),nid(i+1,j+1),nid(i,j+1)
            B=np.zeros(8)
            # dofs order u1 v1 u2 v2 u3 v3 u4 v4
            B[0]=-1/(2*b);B[2]=-1/(2*b);B[4]=1/(2*b);B[6]=1/(2*b)
            B[1]=-1/(2*a);B[7]=-1/(2*a);B[3]=1/(2*a);B[5]=1/(2*a)
            dofs=[2*n1,2*n1+1,2*n2,2*n2+1,2*n3,2*n3+1,2*n4,2*n4+1]
            add(dofs,G*a*b*np.outer(B,B))
    for (nm,dof,k) in SPRINGS:
        rows.append(dof);cols.append(dof);vals.append(k)
    K=sp.csr_matrix((vals,(rows,cols)),shape=(NDOF,NDOF))
    Kreg=sp.identity(NDOF,format='csr')*kreg
    return K,Kreg

def panel_B(i,j):
    a=72.0;b=360.0
    n1,n2,n3,n4=nid(i,j),nid(i+1,j),nid(i+1,j+1),nid(i,j+1)
    dofs=[2*n1,2*n1+1,2*n2,2*n2+1,2*n3,2*n3+1,2*n4,2*n4+1]
    B=np.zeros(8)
    B[0]=-1/(2*b);B[2]=-1/(2*b);B[4]=1/(2*b);B[6]=1/(2*b)
    B[1]=-1/(2*a);B[7]=-1/(2*a);B[3]=1/(2*a);B[5]=1/(2*a)
    return dofs,B

def trib(coords):
    t=np.zeros(len(coords))
    for k in range(len(coords)):
        lo=coords[k]-coords[k-1] if k>0 else 0
        hi=coords[k+1]-coords[k] if k<len(coords)-1 else 0
        t[k]=(lo+hi)/2
    return t
TX=trib(XN); TY=trib(YN)

def load_vector(case, sign_e=+1, ecc_mode='polar'):
    """case: dict(type='wind'|'seis', dir='x'|'y', F=kip, e=ft (eccentricity) )"""
    F=np.zeros(NDOF)
    d=case['dir']; Ftot=case['F']
    if case['type']=='wind':
        if d=='x':
            for i in (0,NXn-1):
                for j in range(NYn):
                    F[2*nid(i,j)]+=Ftot/2*TY[j]/180.0
        else:
            for j in (0,NYn-1):
                for i in range(NXn):
                    F[2*nid(i,j)+1]+=Ftot/2*TX[i]/240.0
    else:
        A=np.outer(TX,TY)  # (41,7) tributary areas, sum=43200
        for i in range(NXn):
            for j in range(NYn):
                f=Ftot*A[i,j]/A.sum()
                F[2*nid(i,j)+(0 if d=='x' else 1)]+=f
    e=case.get('e',0.0)
    if e:
        T=Ftot*e*sign_e   # kip-ft, CCW positive
        xc,yc=120.0,90.0
        if ecc_mode=='polar':
            if case['type']=='wind':
                # distribute couple over the same nodes as wind? use polar over plan area
                pass
            A=np.outer(TX,TY)
            J=0.0
            for i in range(NXn):
                for j in range(NYn):
                    J+=A[i,j]*((XN[i]-xc)**2+(YN[j]-yc)**2)
            for i in range(NXn):
                for j in range(NYn):
                    rx,ry=XN[i]-xc,YN[j]-yc
                    F[2*nid(i,j)]+=-T*A[i,j]*ry/J
                    F[2*nid(i,j)+1]+=T*A[i,j]*rx/J
        elif ecc_mode=='shift':
            # linear variation of the in-direction load across the perpendicular axis (resultant shifted by e)
            A=np.outer(TX,TY)
            if d=='x':
                Iy=sum(A[i,j]*(YN[j]-yc)**2 for i in range(NXn) for j in range(NYn))
                for i in range(NXn):
                    for j in range(NYn):
                        # moment of x-forces about centre = -sum f*(y-yc) ; want = T (ccw) -> f = -T*A*(y-yc)/Iy
                        F[2*nid(i,j)]+=-T*A[i,j]*(YN[j]-yc)/Iy
            else:
                Ix=sum(A[i,j]*(XN[i]-xc)**2 for i in range(NXn) for j in range(NYn))
                for i in range(NXn):
                    for j in range(NYn):
                        F[2*nid(i,j)+1]+=T*A[i,j]*(XN[i]-xc)/Ix
    return F

def solve(Gpanel, F, kreg=1e-3):
    K,Kreg=assemble(Gpanel,kreg)
    Kt=(K+Kreg).tocsc()
    U=spl.spsolve(Kt,F)
    # results
    res={}
    res['U']=U
    q=np.zeros((40,6))
    for i in range(40):
        for j in range(6):
            G=Gpanel[i,j]
            if G<=0: continue
            dofs,B=panel_B(i,j)
            q[i,j]=G*(B@U[dofs])   # kip/in
    res['q_plf']=q*12000.0
    # bar forces
    bf={}
    for (n1,n2,d,ea,Lb,tag) in BARS:
        off=0 if d=='x' else 1
        bf[tag]=ea/Lb*(U[2*n2+off]-U[2*n1+off])
    res['bar']=bf
    # frame forces
    ff={}
    for (nm,dof,k) in SPRINGS:
        ff[nm]=ff.get(nm,0.0)+k*U[dof]
    res['frame']=ff
    res['reg_force']=kreg*U
    res['F']=F
    return res
