import numpy as np, fem, loads as L, demand as D
def panel_G_from_cells(Gcell):
    """Gcell (40,30) kip/in, 0 for void. Series across the 5 cells of each 6x30 panel."""
    Gp=np.zeros((40,6))
    for i in range(40):
        for j in range(6):
            g=Gcell[i,5*j:5*j+5]
            if np.any(g<=0): Gp[i,j]=0.0
            else: Gp[i,j]=5.0/np.sum(1.0/g)
    return Gp

def cases(Fpx=None, wind_case2=True):
    Fpx=L.FPX if Fpx is None else Fpx
    cs={}
    cs['S05']=[dict(type='wind',dir='x',F=L.WIND_X,e=0.0)]
    cs['S06']=[dict(type='wind',dir='y',F=L.WIND_Y,e=0.0)]
    if wind_case2:
        cs['S05'].append(dict(type='wind',dir='x',F=0.75*L.WIND_X,e=0.15*180))
        cs['S06'].append(dict(type='wind',dir='y',F=0.75*L.WIND_Y,e=0.15*240))
    cs['S07']=[dict(type='seis',dir='x',F=Fpx,e=0.05*180)]
    cs['S08']=[dict(type='seis',dir='y',F=Fpx,e=0.05*240)]
    cs['S10']=[dict(type='seis',dir='x',F=Fpx,e=0.05*180,omega=L.OMEGA0)]
    return cs

def collector_bars(direction):
    """perimeter bars within one bay (30 ft) of a braced frame of that direction"""
    tags=set()
    for nm,(d,wall,b0,b1,k) in fem.FRAMES.items():
        if d.lower()!=direction: continue
        lo,hi=max(b0-30,0),min(b1+30,240 if d=='X' else 180)
        if d=='X':
            j=int(round(wall/30))
            for i in range(40):
                x0,x1=6*i,6*i+6
                if x0>=lo-1e-9 and x1<=hi+1e-9: tags.add(('G',i,j))
        else:
            i=int(round(wall/6))
            for j in range(6):
                y0,y1=30*j,30*j+30
                if y0>=lo-1e-9 and y1<=hi+1e-9: tags.add(('J',i,j))
    return tags

def chord_bars(direction):
    tags=set()
    if direction=='y':   # diaphragm spans in x; chords along y=0 and y=180
        for j in (0,6):
            for i in range(40): tags.add(('G',i,j))
    else:
        for i in (0,40):
            for j in range(6): tags.add(('J',i,j))
    return tags

def run_case(Gp, case, sign_e=+1, ecc_mode='polar', kreg=1e-3):
    F=fem.load_vector(case, sign_e, ecc_mode)
    r=fem.solve(Gp,F,kreg)
    d=case['dir']
    U=r['U']
    comp=0 if d=='x' else 1
    disp=U[comp::2].reshape(fem.NYn,fem.NXn)  # [j,i]
    # frame displacements (dir)
    fr={}
    for nm,(fd,wall,b0,b1,k) in fem.FRAMES.items():
        if fd.lower()!=d: continue
        fr[nm]=r['frame'][nm]/k   # avg drift of frame = force/k
    adve=np.mean([abs(v) for v in fr.values()])
    maxdisp=np.max(np.abs(disp))
    # diaphragm deflection relative to the line between the two frame lines
    if d=='y':
        west=np.mean([abs(fr[n]) for n in fr if fem.FRAMES[n][1]==0.0])
        east=np.mean([abs(fr[n]) for n in fr if fem.FRAMES[n][1]==240.0])
        rel=np.max(np.abs(disp)-(west+(east-west)*fem.XN[None,:]/240.0))
    else:
        south=np.mean([abs(fr[n]) for n in fr if fem.FRAMES[n][1]==0.0])
        north=np.mean([abs(fr[n]) for n in fr if fem.FRAMES[n][1]==180.0])
        rel=np.max(np.abs(disp)-(south+(north-south)*fem.YN[:,None]/180.0))
    rel_avg=maxdisp-adve
    chord=max(abs(r['bar'][t]) for t in chord_bars(d))
    coll=max(abs(r['bar'][t]) for t in collector_bars(d))
    regshare=np.abs(r['reg_force'][comp::2].sum())/abs(r['F'][comp::2].sum())
    regabs=np.abs(r['reg_force']).sum()/np.abs(r['F']).sum()
    return dict(q=r['q_plf'],maxq=np.max(np.abs(r['q_plf'])),maxdisp=maxdisp,rel=rel,rel_avg=rel_avg,adve=adve,
                chord=chord,coll=coll*case.get('omega',1.0),coll_raw=coll,frames=r['frame'],fr_disp=fr,
                regshare=regshare,regabs=regabs,res=r)

def run_all(Gcell, ecc_modes=('polar',), signs=(+1,-1), wind_case2=True):
    Gp=panel_G_from_cells(Gcell)
    out={}
    for scn,cl in cases(wind_case2=wind_case2).items():
        rs=[]
        for c in cl:
            if c.get('e',0):
                for m in ecc_modes:
                    for s in signs:
                        rs.append(run_case(Gp,c,s,m))
            else:
                rs.append(run_case(Gp,c))
        out[scn]=rs
    return out
