import numpy as np, pickle
import catalogue as C, loads as L, demand as D, lateral as LT, fem
RATE_DECK={22:3.05,20:3.48,18:4.42,16:5.61}
RATE_FAST=1.35; RATE_SL={'SCREW-10':1.15,'BP':0.32}
IND_ZONE=900; IND_RECT=260; IND_GAGE=4800; IND_PAT=1400
PHI_D=0.70; PHI_T=0.50
SURCH=pickle.load(open('/work/surch.pkl','rb'))

def spec_props(g,n,st,ns):
    pat='36/%d'%n
    Sn=C.sn_tab(g,pat,st,ns); Gp=C.gp_tab(g,pat,st,ns)
    grav=C.allow_total(g); dcap=C.defl_cap(g)
    upl=PHI_T*C.PNOV_TAB[g]*n/18.0 + 0.9*(C.WT[g]+L.ROOFING)
    return dict(Sn=Sn,phiSn=PHI_D*Sn,G=Gp,grav=grav,dcap=dcap,upl=upl,
                endr=C.ENDR[g])

def surch(scn,closed=False,sup=False):
    return SURCH[(scn,closed,sup)]

def cell_maps(zones):
    """zones: list of dict(id, rects=[(x0,y0,x1,y1)], g, n, st, ns). returns per-cell arrays"""
    Z=-np.ones((D.NX,D.NY),int)
    for zi,z in enumerate(zones):
        for (x0,y0,x1,y1) in z['rects']:
            i0,i1=int(round(x0/6)),int(round(x1/6)); j0,j1=int(round(y0/6)),int(round(y1/6))
            if np.any(Z[i0:i1,j0:j1]>=0): raise ValueError('overlap in zone %s rect %s'%(z['id'],(x0,y0,x1,y1)))
            Z[i0:i1,j0:j1]=zi
    return Z

def check(zones, closed=False, sup=False, verbose=True, lateral=True, ecc_modes=('polar',), wind_case2=True):
    issues=[]
    Z=cell_maps(zones)
    # coverage / void
    cov_missing=np.sum((Z<0)&(~D.VOID)); over_void=np.sum((Z>=0)&D.VOID)
    if cov_missing: issues.append('coverage: %d deck cells not covered'%cov_missing)
    if over_void: issues.append('deck over opening: %d cells'%over_void)
    # zoning rules
    gages=set(z['g'] for z in zones); pats=set((z['n'],z['st'],z['ns']) for z in zones)
    nrect=sum(len(z['rects']) for z in zones)
    if len(gages)>2: issues.append('gages %d>2'%len(gages))
    if len(pats)>3: issues.append('patterns %d>3'%len(pats))
    if len(zones)>12: issues.append('zones>12')
    if nrect>14: issues.append('rectangles %d>14'%nrect)
    for z in zones:
        if z['g']==16: issues.append('16 ga not procurable (14 wk > 9 wk)')
        if z['st']=='BP' and z['g'] in (18,16): issues.append('BP on %d ga zone %s'%(z['g'],z['id']))
        if z['ns']<2: issues.append('ns<2 zone %s'%z['id'])
        for (x0,y0,x1,y1) in z['rects']:
            for v in (x0,y0,x1,y1):
                if abs(v/6-round(v/6))>1e-9: issues.append('off-grid rect %s'%z['id'])
    # boundary rule 10.4: zone touching perimeter or opening edge
    def touches_boundary(z):
        for (x0,y0,x1,y1) in z['rects']:
            if x0<=0 or y0<=0 or x1>=240 or y1>=180: return True
