import numpy as np, time
import demand as D, design as DS
NX,NY=D.NX,D.NY
def prefix(M):
    P=np.zeros((M.shape[0]+1,M.shape[1]+1))
    P[1:,1:]=np.cumsum(np.cumsum(M,0),1)
    return P
def rsum(P,a,b,c,d):
    return P[b,d]-P[a,d]-P[b,c]+P[a,c]
INF=1e18
def run_dp(specs, req_ok, xlines, ylines, Kmax=14, verbose=True, rect_cost=None):
    xl=list(xlines); yl=list(ylines)
    nxl,nyl=len(xl),len(yl)
    V=prefix(D.VOID.astype(float))
    badP=[prefix((~ok).astype(float)) for ok in req_ok]
    rate=[DS.RATE_DECK[g]+n/18.0*DS.RATE_FAST+ns/18.0*DS.RATE_SL[st] for (g,n,st,ns) in specs]
    bcap=[(n>=7 and ns>=3) for (g,n,st,ns) in specs]
    RC=DS.IND_RECT if rect_cost is None else rect_cost
    F=np.full((nxl,nxl,nyl,nyl,Kmax+1),INF)
    LEAF={}
    # anti-diagonal masks
    kk=np.add.outer(np.arange(Kmax+1),np.arange(Kmax+1))
    t0=time.time()
    order=sorted([(ia,ib,ic,idd) for ia in range(nxl) for ib in range(ia+1,nxl) for ic in range(nyl) for idd in range(ic+1,nyl)],
                 key=lambda r:(xl[r[1]]-xl[r[0]])*(yl[r[3]]-yl[r[2]]))
    for (ia,ib,ic,idd) in order:
        a,b,c,d=xl[ia],xl[ib],yl[ic],yl[idd]
        f=np.full(Kmax+1,INF)
        ncell=(b-a)*(d-c); nvoid=rsum(V,a,b,c,d)
        if nvoid==ncell:
            f[:]=0.0
        elif nvoid==0:
            tb=(a==0 or c==0 or b==NX or d==NY)
            if not tb:
                s=rsum(V,a,b,max(c-1,0),c)+rsum(V,a,b,d,min(d+1,NY))+rsum(V,max(a-1,0),a,c,d)+rsum(V,b,min(b+1,NX),c,d)
                tb=s>0
            best=INF;bs=None
            for si in range(len(specs)):
                if tb and not bcap[si]: continue
                if rsum(badP[si],a,b,c,d)>0: continue
                cst=ncell*36.0*rate[si]+RC
                if cst<best: best=cst;bs=si
            if bs is not None:
                f[1:]=best; LEAF[(ia,ib,ic,idd)]=(bs,best)
        cuts1=[];cuts2=[]
        for ie in range(ia+1,ib):
            cuts1.append(F[ia,ie,ic,idd]); cuts2.append(F[ie,ib,ic,idd])
        for ie in range(ic+1,idd):
            cuts1.append(F[ia,ib,ic,ie]); cuts2.append(F[ia,ib,ie,idd])
        if cuts1:
            A1=np.array(cuts1); A2=np.array(cuts2)
            Mm=np.min(A1[:,:,None]+A2[:,None,:],axis=0)
            h=np.full(Kmax+1,INF)
            for k in range(Kmax+1):
                h[k]=Mm[kk==k].min() if k<=2*Kmax else INF
            h=np.minimum.accumulate(h)
            f=np.minimum(f,h)
        F[ia,ib,ic,idd]=f
    if verbose: print('dp %d rects time %.1fs'%(len(order),time.time()-t0))
    def recon(r,k,out):
        ia,ib,ic,idd=r
        a,b,c,d=xl[ia],xl[ib],yl[ic],yl[idd]
        target=F[r][k]
        if target>=INF/2: raise ValueError('infeasible')
        if target==0.0 and rsum(V,a,b,c,d)==(b-a)*(d-c): return
        if r in LEAF and abs(LEAF[r][1]-target)<1e-6 and k>=1:
            out.append(((a*6,c*6,b*6,d*6),LEAF[r][0])); return
        for ie in range(ia+1,ib):
            r1=(ia,ie,ic,idd); r2=(ie,ib,ic,idd)
            for k1 in range(k+1):
                for k2 in range(k-k1+1):
                    if abs(F[r1][k1]+F[r2][k2]-target)<1e-6:
                        recon(r1,k1,out); recon(r2,k2,out); return
        for ie in range(ic+1,idd):
            r1=(ia,ib,ic,ie); r2=(ia,ib,ie,idd)
            for k1 in range(k+1):
                for k2 in range(k-k1+1):
                    if abs(F[r1][k1]+F[r2][k2]-target)<1e-6:
                        recon(r1,k1,out); recon(r2,k2,out); return
        raise ValueError('recon failed')
    full=(0,nxl-1,0,nyl-1)
    def get(k):
        out=[]; recon(full,k,out); return out
    return F[full], get

def breakpoints(maps):
    """indices of lines (0..NX) where any map changes between neighbours"""
    xs={0,NX}; ys={0,NY}
    for M in maps:
        for i in range(1,NX):
            if np.any(M[i,:]!=M[i-1,:]): xs.add(i)
        for j in range(1,NY):
            if np.any(M[:,j]!=M[:,j-1]): ys.add(j)
    return sorted(xs),sorted(ys)
