import numpy as np, sys, pickle
import demand as D, design as DS, catalogue as C, loads as L, dp
def env_surch(closed=False,sup=False):
    return np.maximum.reduce([DS.surch(s,closed,sup) for s in ('S02','S03','S04')])
def req_maps(specs, S, qcell=None, qmargin=1.0):
    U=np.abs(D.uplift_map())
    oks=[]
    for (g,n,st,ns) in specs:
        p=DS.spec_props(g,n,st,ns)
        Dl=L.COLLATERAL+C.WT[g]
        ok=(Dl+L.PF+S<=p['grav']+1e-9)&(L.PF+S<=p['dcap']+1e-9)&(U<=p['upl']+1e-9)
        if qcell is not None:
            ok&=(qcell*qmargin<=p['phiSn']+1e-9)
        oks.append(ok)
    return oks
def lines_for(specs,S,qcell=None,qmargin=1.0,extra_x=(),extra_y=()):
    oks=req_maps(specs,S,qcell,qmargin)
    code=np.zeros((D.NX,D.NY),int)
    for k,ok in enumerate(oks): code+=ok.astype(int)<<k
    code=np.where(D.VOID,-1,code)
    xs,ys=dp.breakpoints([code])
    xs=sorted(set(xs)|set(extra_x)); ys=sorted(set(ys)|set(extra_y))
    return oks,xs,ys
def solve(specs,S,qcell=None,qmargin=1.0,Kmax=14,extra_x=(),extra_y=(),verbose=True):
    oks,xs,ys=lines_for(specs,S,qcell,qmargin,extra_x,extra_y)
    if verbose: print('lines',len(xs),len(ys))
    f,get=dp.run_dp(specs,oks,xs,ys,Kmax=Kmax,verbose=verbose)
    return f,get
def to_zones(specs,leaves):
    zones={}
    for (r,si) in leaves:
        zones.setdefault(si,[]).append(r)
    out=[]
    for k,(si,rects) in enumerate(sorted(zones.items())):
        g,n,st,ns=specs[si]
        out.append(dict(id='Z%d'%(k+1),rects=rects,g=g,n=n,st=st,ns=ns))
    return out
if __name__=='__main__':
