    if len(leaves)>14: issues.append('rects')
    if len(set(specs))>12: issues.append('zones')
    # boundary rule per rectangle (zone = spec group; if any rect of a spec touches boundary, spec must be bcap)
    for k,(r,s) in enumerate(leaves):
        if s[2]=='BP' and s[0] in (18,16): issues.append('BP on heavy')
