            if D.VOID[i0:i1,max(j0-1,0)].any() or D.VOID[i0:i1,min(j1,D.NY-1)].any() or D.VOID[max(i0-1,0),j0:j1].any() or D.VOID[min(i1,D.NX-1),j0:j1].any():
                tb=True
        spec_touch[s]=spec_touch.get(s,False) or tb
    for s,tb in spec_touch.items():
        if tb and (s[1]<7 or s[3]<3): issues.append('10.4 %s'%(s,))
    # cell checks
    G=np.zeros((D.NX,D.NY)); PHI=np.zeros((D.NX,D.NY))
    worst={}
    for k,(r,s) in enumerate(leaves):
        p=DS.spec_props(*s)
        x0,y0,x1,y1=r; i0,i1,j0,j1=x0//6,x1//6,y0//6,y1//6
        G[i0:i1,j0:j1]=p['G']; PHI[i0:i1,j0:j1]=p['phiSn']
        Dl=L.COLLATERAL+C.WT[s[0]]
        for scn,M in SM.items():
            sub=M[i0:i1,j0:j1]
            if np.any(Dl+L.PF+sub>p['grav']+1e-6): issues.append('%s strength rect %s'%(scn,r))
            if np.any(L.PF+sub>p['dcap']+1e-6): issues.append('%s defl rect %s'%(scn,r))
        if np.any(U_MAP[i0:i1,j0:j1]>p['upl']+1e-6): issues.append('uplift rect %s'%(r,))
    G=np.where(D.VOID,0,G)
    res=dict(issues=issues,G=G,PHI=PHI,Z=Z)
    if lateral:
        out=FF.run_all(G,modes=modes)
        summ={}
        for scn,rs in out.items():
