            ratio=np.where(deck,qcell*margins['q']/np.maximum(PHI,1e-9),0)
            s=dict(maxq=max(r['maxq'] for r in rs),qratio=ratio.max(),rel=max(r['rel'] for r in rs),rel_avg=max(r['rel_avg'] for r in rs),
                   coll=max(r['coll'] for r in rs),chord=max(r['chord'] for r in rs),reg=max(r['reg'] for r in rs),adve=np.mean([r['adve'] for r in rs]))
            summ[scn]=s
            if s['qratio']>1+1e-9: issues.append('%s shear ratio %.3f'%(scn,s['qratio']))
            if max(s['rel'],s['rel_avg'])>margins['defl']: issues.append('%s defl %.3f'%(scn,max(s['rel'],s['rel_avg'])))
            if s['coll']>margins['coll']: issues.append('%s coll %.2f'%(scn,s['coll']))
            if s['chord']>margins['chord']: issues.append('%s chord %.2f'%(scn,s['chord']))
        res['summ']=summ; res['lat']=out
    # cost
    cost=0
    for (r,s) in leaves:
        x0,y0,x1,y1=r; A=(x1-x0)*(y1-y0)
        cost+=A*(DS.RATE_DECK[s[0]]+s[1]/18*DS.RATE_FAST+s[3]/18*DS.RATE_SL[s[2]])+DS.IND_RECT
    cost+=DS.IND_ZONE*len(set(specs))+DS.IND_GAGE*len(gset)+DS.IND_PAT*len(pset)
    res['cost']=cost
    if verbose:
        print('cost %.0f issues %s'%(cost,issues[:12]))
        if lateral:
