import numpy as np, pickle, demand as D, loads as L, design as DS, catalogue as C
TABLE_ALLOW={22:106.0,20:130.0,18:177.0,16:222.0}
def grav_cap(g): return min(TABLE_ALLOW[g], C.allow_total(g))
def surch_variant(scn, closed, sup, ends=True):
    """sup=True computed without thin-wall end faces"""
    if not sup: return DS.surch(scn,closed,False)
    key=(scn,closed,'sup_noends')
    if key in _cache: return _cache[key]
    strips=L.all_strips(L.GROUPS[scn])
    def is_end(d):
        if d['obs']=='SCR-N' and d['face'] in ('W','E'): return True
        if d['obs']=='SCR-E' and d['face'] in ('S','N'): return True
        return False
    strips=[d for d in strips if not is_end(d)]
    S=np.zeros((D.NX,D.NY))
    for wd in sorted(set(d['wind'] for d in strips)):
        ds=[d for d in strips if d['wind']==wd]
        for i in range(D.NX):
            for j in range(D.NY):
                act=[d for d in ds if L.cell_max_strip(d,D.XS[i],D.XS[i+1],D.YS[j],D.YS[j+1],closed)>0]
                if not act: continue
                best=max(L.cell_max_strip(d,D.XS[i],D.XS[i+1],D.YS[j],D.YS[j+1],closed) for d in act)
                if len(act)>1:
                    n=25; e=0 if closed else 1e-6
                    xs=np.linspace(D.XS[i]+e,D.XS[i+1]-e,n); ys=np.linspace(D.YS[j]+e,D.YS[j+1]-e,n)
                    X,Y=np.meshgrid(xs,ys,indexing='ij'); tot=np.zeros_like(X)
                    for d in act:
                        fn,box=L.strip_value_fn(d)
                        inb=(X>=box[0]-1e-9)&(X<=box[1]+1e-9)&(Y>=box[2]-1e-9)&(Y<=box[3]+1e-9)
                        x0,x1,y0,y1=box; f=d['face']; pk,w=d['peak'],d['w']
                        if d['obs']=='PARAPET':
                            raise ValueError
                        ox0,ox1,oy0,oy1=d['box']
                        if f=='E': dist=X-ox1
                        elif f=='W': dist=ox0-X
                        elif f=='N': dist=Y-oy1
                        else: dist=oy0-Y
                        val=np.where(inb,pk*np.clip(1-np.maximum(dist,0)/w,0,None),0)
                        tot+=val
                    best=max(best,tot.max())
                S[i,j]=max(S[i,j],best)
    _cache[key]=S
    return S
_cache={}
