def save_cache(): pickle.dump(_cache,open('/work/surch_sup_noends.pkl','wb'))
def envelope(variants):
    """variants: list of (closed,sup). returns dict scn->map (max over variants)"""
    out={}
    for scn in ('S02','S03','S04'):
        out[scn]=np.maximum.reduce([surch_variant(scn,c,s) for (c,s) in variants])
