import numpy as np, specopt as SO
def greedy(P, assign, verbose=True, max_rounds=20):
    cur=list(assign)
    o,p,v=P.objective(cur)
    if p>0:
        print('start infeasible pen',p); 
    n=len(cur)
    for rnd in range(max_rounds):
        improved=False
        cands=[]
        # single rect changes
        for ri in range(n):
            for si in range(len(P.specs)):
                if si==cur[ri] or not P.static_ok[ri,si]: continue
                c=list(cur); c[ri]=si
                cands.append(c)
        # pattern substitutions
        pats=set(P.specs[a][1:] for a in cur)
        for pold in pats:
            for pnew in SO.PATS:
                if pnew==pold: continue
                c=list(cur); okk=True
                for ri in range(n):
                    s=P.specs[c[ri]]
                    if s[1:]==pold:
                        ns=(s[0],)+pnew
                        if ns not in P.sidx: okk=False;break
                        c[ri]=P.sidx[ns]
                if okk: cands.append(c)
        # gage swaps for rect
        cands.sort(key=lambda c:P.cost(c))
        base=P.cost(cur)
        for c in cands:
            if P.cost(c)>=base-1e-6: break
            o2,p2,v2=P.objective(c)
            if p2==0:
                cur=c; o,p,v=o2,p2,v2; improved=True
                if verbose: print('round',rnd,'cost',round(P.cost(cur)))
                break
        if not improved: break
    return cur
